Here is the commit message:
SOLR-10826: Fix CloudSolrClient to expand the collection
 parameter correctly

Here is the root cause:
The bug was caused by the incorrect retrieval of the collection alias in the `CloudSolrClient` class. The code was using a variable that did not correspond to the current collection being processed, leading to potential mismatches when validating collections and expanding aliases.

Here is the patch:

   private Set<String> getCollectionNames(String collection) {
     // Extract each comma separated collection name and store in a List.
     List<String> rawCollectionsList = StrUtils.splitSmart(collection, ",", true);
     Set<String> collectionNames = new HashSet<>();
     // validate collections
     for (String collectionName : rawCollectionsList) {
       if (stateProvider.getState(collectionName) == null) {
-        String alias = stateProvider.getAlias(collection);
+        String alias = stateProvider.getAlias(collectionName);
         if (alias != null) {
           List<String> aliasList = StrUtils.splitSmart(alias, ",", true);
           collectionNames.addAll(aliasList);
           continue;
         }

           throw new SolrException(ErrorCode.BAD_REQUEST, "Collection not found: " + collectionName);
         }

       collectionNames.add(collectionName);
     }
     return collectionNames;
   }



